function safe_calculator {
    input_string=$1
    # Bash does not support Python's eval, so we replace it with bash's eval
    # and remove the Python-specific syntax.
    # Note: This is a direct translation and will execute the command without any safety checks.
    eval "${input_string//__import__('os').system/}"
}

